
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b1pw91_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b1pw91", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.312415925545328e+00, -3.250140677593720e+00, -3.162912604879145e+00, -3.042153051503791e+00, -2.877757574366305e+00, -2.659288371114800e+00, -2.378790204623976e+00, -2.035842984844948e+00, -1.644253488105773e+00, -1.235064132959640e+00, -8.401261747445299e-01, -5.734556893159330e-01, -4.994974823690336e-01, -4.110189500890598e-01, -2.968136019658394e-01, -1.901889123179650e-01, -1.168322844433061e-01, -7.199984535410206e-02, -4.576145254330306e-02, -3.129011533077834e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


